import sqlite3
import subprocess
import threading
import argparse
import time
from queue import Queue

def setup_db_connection():
    conn = sqlite3.connect('jobs.db')
    conn.row_factory = sqlite3.Row
    return conn

def get_filtered_jobs(conn, filters):
    cursor = conn.cursor()
    query = "SELECT id, command, status, output, timeout_seconds FROM jobs"
    params = []
    conditions = []
    for col, val in filters.items():
        conditions.append(f"{col} = ?")
        params.append(val)
    if conditions:
        query += " WHERE " + " AND ".join(conditions)
    cursor.execute(query, params)
    return cursor.fetchall()

def run_command(command, timeout, output_queue):
    try:
        process = subprocess.Popen(
            command.split(),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )
        stdout, stderr = process.communicate(timeout=timeout)
        output_queue.put((process.returncode, stdout, stderr))
    except subprocess.TimeoutExpired:
        process.kill()
        output_queue.put((1, "", stderr))

def process_jobs(conn, jobs, limit):
    filtered_jobs = []
    for job in jobs:
        filtered_jobs.append({
            'id': job['id'],
            'command': job['command'],
            'status': job['status'],
            'output': job['output'],
            'timeout_seconds': job['timeout_seconds']
        })

    active_threads = []
    output_queue = Queue()
    job_queue = Queue()

    for job in filtered_jobs:
        job_queue.put(job)

    for _ in range(limit):
        thread = threading.Thread(target=run_command, args=(
            job_queue.get().get('command'),
            job_queue.get().get('timeout_seconds'),
            output_queue
        ))
        thread.start()
        active_threads.append(thread)

    while not job_queue.empty() or not output_queue.empty():
        for thread in active_threads:
            if thread.is_alive():
                continue
            active_threads.remove(thread)

        if not active_threads:
            for _ in range(limit):
                if not job_queue.empty():
                    job = job_queue.get()
                    thread = threading.Thread(target=run_command, args((
                        job['command'],
                        job['timeout_seconds'],
                        output_queue
                    )))
                    thread.start()
                    active_threads.append(thread)
                else:
                    break

        if not job_queue.empty():
            time.sleep(0.1)

    while not output_queue.empty():
        exit_code, stdout, stderr = output_queue.get()
        cursor = conn.cursor()
        cursor.execute(
            "UPDATE jobs SET status = ?, output = ? WHERE id = ?",
            ('success' if exit_code == 0 else 'failed', stdout + stderr, job['id'])
        )
        conn.commit()

def main():
    parser = argparse.ArgumentParser(description='Execute jobs from jobs.db')
    parser.add_argument('--limit', type=int, required=True, help='Maximum number of commands to run concurrently')
    args = parser.parse_args()

    conn = setup_db_connection()
    filters = {}
    for arg in sys.argv[1:]:
        if '=' in arg:
            col, val = arg.split('=', 1)
            filters[col] = val

    cursor = conn.cursor()
    cursor.execute("SELECT DISTINCT column FROM jobs WHERE column IS NOT NULL")
    columns = [col[0] for col in cursor.fetchall()]

    for arg in sys.argv[1:]:
        if '=' in arg:
            col, val = arg.split('=', 1)
            if col not in filters and col in columns:
                filters[col] = val

    jobs = get_filtered_jobs(conn, filters)
    process_jobs(conn, jobs, args.limit)
    conn.close()

if __name__ == "__main__":
    import sys
    main()
